import {ARCHITECTURE_PARTS,architectureSVG} from './architecture.js';
import {CASCADE_BRANCHES,branchStatus,cascadeSVG} from './cascade.js';
import {INITIAL,LABELS,EVENT_COPY,VERSION,evaluate,rating,snapshot} from './engine.js';
import {GRAPH_NODES,graphSVG} from './graph.js';
let state={...INITIAL};let result;let openEntryId=null;
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=id=>id.replace('P01-','');
const options=(labels,value)=>Object.entries(labels).map(([v,l])=>`<option value="${v}"${v===value?' selected':''}>${l}</option>`).join('');
function entryExplanation(e){return `<p>${escape(e.description)}</p>${state.event||e.status?`<p class="entry-assessment"><strong>Im gewählten Fall:</strong> ${escape(e.reason)}</p>`:''}<h3>Wie hilft Git?</h3><p>${escape(e.git)}</p><h3>Was gibt es zu bedenken?</h3><p>${escape(e.consider)}</p><p><strong>Handlung:</strong> ${escape(e.action)}</p><p><strong>Zuständig:</strong> ${escape(e.role)}</p>${e.sources?`<div class="resource-links">${e.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${escape(label)} ↗</a>`).join('')}</div>`:''}`;}
function selectedGraph(){
 $('#decision-graph').innerHTML=graphSVG(state,true);
 $('#graph-text').innerHTML=`<ol><li>Anna wählt ein Arbeitsformat: TEI mit oXygen Author oder Markdown im Texteditor mit Vorschau. Beide Wege führen zu Git-gestützten Quelldaten; Prüfungen und Semantik bleiben unterschiedlich. Aktuell: ${LABELS.format[state.format]}.</li><li>Privater Arbeitsort: institutionelles GitLab oder ein anderer geeigneter Dienst, etwa GitHub. Aktuell: ${LABELS.host[state.host]}. Beratung ist eine gesonderte Leistung.</li><li>Der Publikations-Host wird eigenständig gewählt: gleicher oder anderer Dienst. Auf beiden Wegen bleibt ein eigenes bereinigtes Publikationsrepo vorgesehen. Aktuell: ${LABELS.publicationHost[state.publicationHost]}.</li><li>Nach fachlicher Freigabe führen die Wege zu einem geprüften Release. Aktuelle Freigabeabsicht: ${LABELS.release[state.release]}. Ein noch interner Stand ist kein öffentlicher Release.</li><li>Mögliche Ergebnisse: Editionsdaten mit vereinbarter Archivübergabe, eine statische Website und eine optionale Druckfassung. Website und Druck benötigen passende Ausgabewege; Archivierung eine eigene Vereinbarung.</li></ol><p>Die Knoten erläutern Optionen, keine bereits abgeschlossenen Arbeiten. Ein Hostwechsel bleibt mit geprüftem Export möglich.</p>`;
 $('#choice-effects').innerHTML=`<h4>Was diese Auswahl bedeutet</h4><ul>${[result.formatText,result.hostText,result.releaseText,result.experienceText].map(t=>`<li>${t}</li>`).join('')}</ul>`;
}
function eventPanel(){
 document.querySelectorAll('[data-event]').forEach(b=>b.setAttribute('aria-pressed',String(state.event===b.dataset.event)));
 $('#clear-event').hidden=!state.event;
 const e=EVENT_COPY[state.event];if(!e){$('#event-detail').innerHTML='<p class="small">Wählen Sie ein Ereignis, um Änderungen gegenüber Ihrer Ausgangsauswahl zu sehen.</p>';return;}
 let fields='';
 if(state.event==='leaving')fields=`<div class="event-fields">${[['access','Repo-Zugang am bisherigen Arbeitsort'],['advice','Bisherige Beratung'],['license','Bisheriger oXygen-/TEI-Werkzeugzugang'],['publicationService','Institutionelle Publikationsdienste']].map(([key,label])=>`<div><label for="event-${key}">${label}</label><select id="event-${key}" data-condition="${key}" ${key==='license'&&state.format==='markdown'?'disabled':''}>${options(LABELS.availability,state[key])}</select></div>`).join('')}</div><p class="small">${state.format==='markdown'?'Die oXygen-Bedingung ist für den gewählten Markdown-Weg nicht anwendbar. ':''}${state.host==='uni-only'?'Ohne angebotene Beratung bestand bereits vorher eine Versorgungslücke. ':''}Beim anderen Dienst meint „Repo-Zugang endet“ eine eigens bestätigte Abhängigkeit; dies folgt nicht aus dem Institutionswechsel.</p><button class="text-button" type="button" id="load-leaving">Testfall laden: alle vier bisherigen Dienste enden</button><section class="cascade-section"><h5>Eine Ursache. Mehrere mögliche Folgen.</h5><p>Die vier Zweige zeigen die gemeinsamen Abhängigkeiten und passende Reaktionen. Wählen Sie einen Knoten für eine Erklärung.</p><div class="cascade-viewport" tabindex="0" role="region" aria-label="Folgegraph, auf schmalen Ansichten scrollbar"><div id="cascade-graph"></div></div><div id="cascade-explanation" class="graph-explanation" role="status" aria-live="polite">Die Bedingungen oben bestimmen die Statusangaben im Graphen. Weiterarbeit ist das Ziel der Maßnahmen, kein schon nachgewiesenes Ergebnis.</div><div class="graph-downloads"><a href="assets/anna-folgekette.svg" download>Folgegraph als SVG ↓</a><a href="assets/anna-folgekette.pdf" download>PDF, A4 quer ↓</a><a href="assets/anna-folgekette.png" download>PNG ↓</a><button type="button" id="download-current-cascade">Aktueller Testfall als SVG ↓</button></div><details><summary>Folgekette als Text lesen</summary><div id="cascade-text"></div></details></section>`;
 if(state.event==='crash')fields=`<div class="event-fields"><div><label for="event-sync">Letzter Repo-Stand extern abgeglichen?</label><select id="event-sync" data-condition="sync">${options(LABELS.proof,state.sync)}</select></div><div><label for="event-backup">Unabhängige Sicherung mit geprüftem Rückweg?</label><select id="event-backup" data-condition="backup">${options(LABELS.proof,state.backup)}</select></div></div><p class="small">„Ja“ ist eine zusätzliche, ausdrücklich gesetzte Modellannahme. Aktualität und Umfang bestimmen, welche Arbeit vorhanden ist. Der Defekt wird als eingetreten außerhalb der Wahrscheinlichkeitsmatrix geführt.</p>`;
 const guide=state.event==='leaving'?`<a class="text-link" href="#repo-umzug" data-open-guide>So zieht Anna ihr Repo selbst um: die Anleitung ↗</a>`:'';
 $('#event-detail').innerHTML=`<div class="event-panel"><p class="eyebrow">EINE MÖGLICHE SITUATION</p><h4>${e.title}</h4><div class="event-story">${e.story.map(p=>`<p>${p}</p>`).join('')}</div>${guide}<h5 class="event-question">Was hat Anna bereits geklärt?</h5>${fields}<p><strong>Nächster Schritt:</strong> ${e.task}</p><p class="small">Zuständig: ${e.role}</p></div>`;
 if(state.event==='leaving')renderCascade();
}
function matrix(type){
 const entries=result.entries.filter(e=>e.type===type);const cells=[];
 for(const w of ['hoch','mittel','niedrig']){cells.push(`<div class="matrix-tick">${w}</div>`);for(const p of ['niedrig','mittel','hoch'])cells.push(`<div class="matrix-cell" aria-label="Wirkung ${w}, Plausibilität ${p}">${entries.filter(e=>!e.status&&e.p===p&&e.w===w).map(chip).join('')}</div>`);}
 cells.push('<div class="matrix-tick"></div>',...['niedrig','mittel','hoch'].map(t=>`<div class="matrix-tick">${t}</div>`));
 const unknown=entries.filter(e=>e.p==='ungeklärt'&&!e.status);const statuses=entries.filter(e=>e.status);
 return `<div class="matrix-wrap"><div class="axis-y">WIRKUNG →</div><div><div class="matrix-grid">${cells.join('')}</div><div class="matrix-axis">PLAUSIBILITÄT →</div></div></div><div class="unknown"><strong>? Plausibilität ungeklärt</strong>${unknown.length?unknown.map(chip).join(' '):'Keine Einträge in dieser Auswahl.'}${statuses.length?`<strong>Gesonderter Status</strong>${statuses.map(e=>`${chip(e)} ${escape(e.status)}`).join('<br>')}`:''}</div>`;
}
function renderArchitecture(){const target=$('#architecture-graph');if(!target)return;target.innerHTML=architectureSVG(state,true);$('#architecture-explanation').textContent='Ansicht zur aktuellen Auswahl. Wählen Sie einen Knoten für die Erklärung; aus der Darstellung folgt keine bereits erfolgte Freigabe oder Archivierung.';$('#architecture-text').innerHTML=`<ol><li><strong>Lokaler Rechner:</strong> ${escape(LABELS.format[state.format])}; Dateien bearbeiten, prüfen und Vorschau ansehen.</li><li><strong>Privates Arbeitsrepo:</strong> ${escape(LABELS.host[state.host])}. Bewusster Abgleich mit dem Rechner; Beratung als eigene Leistung.</li><li><strong>Freigabe und Ausgabe:</strong> geeigneten Stand auswählen, fachlich sowie hinsichtlich Rechte/Metadaten prüfen, interne Notizen bereinigen und Dateien ohne private Git-Geschichte exportieren. Bei Bedarf HTML/PDF erzeugen.</li><li><strong>Eigenes öffentliches Publikationsrepo:</strong> ${escape(LABELS.publicationHost[state.publicationHost])}. Freigegebene Daten, Dokumentation und Releases; optionaler Webzugang benötigt einen passenden Ausgabeweg.</li><li><strong>Archivdienst:</strong> definierten Stand mit Metadaten übergeben; Zugang, langfristige Verantwortung und persistente Kennung gesondert vereinbaren.</li></ol><p>Aktuelle Freigabeabsicht: ${escape(LABELS.release[state.release])}. Alle Ausgaben bleiben geplante Möglichkeiten; externe Sicherung und Wiederherstellung sind eigenständig zu prüfen.</p>`;}
function explainArchitecture(id){const part=ARCHITECTURE_PARTS[id];if(part)$('#architecture-explanation').innerHTML=`<h4>${escape(part.title)}</h4><p>${escape(part.text)}</p>`;}
function downloadArchitecture(){const url=URL.createObjectURL(new Blob([architectureSVG(state,false)],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='anna-architektur-auswahl.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#architecture-graph').addEventListener('keydown',e=>{const node=e.target.closest('[data-architecture-node]');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();explainArchitecture(node.dataset.architectureNode);}});
function renderCascade(){const target=$('#cascade-graph');if(!target)return;target.innerHTML=cascadeSVG(state,true);$('#cascade-explanation').textContent='Status aktualisiert. Wählen Sie einen Zweig für die Erklärung der aktuellen Bedingung und der passenden Reaktion.';$('#cascade-text').innerHTML=`<p>Ende der Universitätsanbindung → vier einzeln zu klärende Bedingungen:</p><ol>${CASCADE_BRANCHES.map(b=>`<li><strong>${escape(b.title.join(' '))}</strong> ${escape(branchStatus(b,state))}. ${escape(b.action.join(' '))}. ${escape(b.explain)}</li>`).join('')}</ol><p>Die Maßnahmen können sich ergänzen und die Weiterarbeit ermöglichen. Erst ihre Prüfung zeigt, ob der neue Arbeits- und Publikationsweg tragfähig ist.</p>`;}
function explainCascade(id){const b=CASCADE_BRANCHES.find(b=>b.id===id);if(b)$('#cascade-explanation').innerHTML=`<h4>${escape(b.title.join(' '))}</h4><p><strong>${escape(branchStatus(b,state))}</strong></p><p>${escape(b.explain)}</p>`;}
function downloadCascade(){const url=URL.createObjectURL(new Blob([cascadeSVG(state,false)],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='anna-folgekette-testfall.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#event-detail').addEventListener('keydown',e=>{const node=e.target.closest('[data-cascade-node]');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();explainCascade(node.dataset.cascadeNode);}});
function chip(e){return `<span class="matrix-topic"><button type="button" class="matrix-chip ${e.type}${result.changes.some(c=>c.after.id===e.id)?' changed':''}" data-open-entry="${e.id}" aria-haspopup="dialog" aria-describedby="preview-${e.id}" aria-label="${escape(e.title)} erklären">${escape(e.title)}</button><span id="preview-${e.id}" class="topic-preview" role="tooltip"><strong>${escape(e.title)}</strong>${escape(e.reason)}<em>Klicken: Erklärung und nächster Schritt</em></span></span>`;}
function registers(){
 $('#chance-matrix').innerHTML=matrix('c');$('#risk-matrix').innerHTML=matrix('r');
 $('#register').innerHTML=`<p class="small">Ausschnitt des Inventars: fünf Chancen und acht Risiken. Bewertungen beziehen sich auf fünf Jahre. Bei ungeklärten Werten ist die Unsicherheit hoch; empirische Häufigkeiten fehlen. Eine geplante Maßnahme ist noch keine nachgewiesene Risikominderung.</p><div class="register-grid">${result.entries.map(e=>`<article class="register-item" id="entry-${e.id}" tabindex="-1"><h4>${e.title}</h4><p><strong>${rating(e)}</strong>${e.status?`; Wirkung: ${e.w}`:''}</p><p>${e.description}</p><button class="text-button" type="button" data-open-entry="${e.id}" aria-haspopup="dialog">Wie hilft Git? Was ist zu bedenken? ↗</button></article>`).join('')}</div>`;
 $('#changes').innerHTML=result.changes.length?result.changes.map(c=>`<div class="change-row changed"><h4>${c.after.title}</h4><p><strong>${rating(c.before)} → ${rating(c.after)}</strong></p><p>${c.after.reason}</p><p><strong>Handlung:</strong> ${c.after.action}</p></div>`).join(''):'<div class="change-row"><p>Aktuell ist kein Ereignis aktiv. Die Matrix zeigt Ihre gewählte Ausgangslage. Ändern Sie eine Entscheidung oder wählen Sie ein Ereignis, um seine begründeten Folgen zu untersuchen.</p></div>';
}
function taskList(){return {anna:['Editionsprinzipien und einen repräsentativen Abschnitt vorbereiten.','Fachliche Änderungen begründen, Mitwirkung würdigen und Freigaben verantworten.','Regelmäßig committen und pushen; Wiederherstellung ausprobieren und den gesicherten Umfang dokumentieren.',...(state.event?[EVENT_COPY[state.event].task]:[])],services:['Arbeitsumgebung, Schema, Validierung und lokale Vorschau verständlich einrichten.','Einen verlässlich betriebenen Git-Dienst sowie verständliche Anleitungen für Wiederherstellung und Repo-Umzug bereitstellen; Sonderfälle gezielt unterstützen.','Rechte-/Metadatenberatung, Archivübergabe und längerfristigen Zugang klären.','Punktuelle Beratung und einen erprobten Export-/Übergabeweg finanzieren.']};}
function strategy(){const tasks=taskList();$('#strategy').innerHTML=`<div class="strategy-summary"><h3>Ihre aktuelle Arbeitsfassung</h3><p><strong>Format:</strong> ${LABELS.format[state.format]}<br><strong>Umgebung:</strong> ${LABELS.host[state.host]}<br><strong>Freigabe:</strong> ${LABELS.release[state.release]}<br><strong>Publikations-Host:</strong> ${LABELS.publicationHost[state.publicationHost]}<br><strong>Ereignis:</strong> ${state.event?LABELS.event[state.event]:'Keines ausgewählt'}</p><p>${result.formatText}</p><p>${result.releaseText}</p><p class="small">Offen: konkrete Bedingungen, Rechte, Budget, Werkzeugberechtigung, Vertretung und Archivträger. Einrichtung, Sicherung und Übergabe sind geplant, nicht als umgesetzt nachgewiesen.</p></div><div class="task-columns"><div><h4>Anna selbst</h4><ul>${tasks.anna.map(t=>`<li>${t}</li>`).join('')}</ul></div><div><h4>Unterstützung ermöglichen</h4><ul>${tasks.services.map(t=>`<li>${t}</li>`).join('')}</ul></div></div>`;}
function render(announce=false,updateEvent=true){result=evaluate(state);selectedGraph();renderArchitecture();if(updateEvent)eventPanel();registers();strategy();if(announce)$('#change-status').textContent=`Auswahl aktualisiert. ${state.event?EVENT_COPY[state.event].title:'Kein Ereignis aktiv.'} ${result.changes.length} Einträge haben gegenüber der gewählten Ausgangslage neue Folgen.`;}
$('#choices').addEventListener('change',e=>{if(e.target.name in INITIAL){state[e.target.name]=e.target.value;render(true);}});
$('#reset').addEventListener('click',()=>{state={...INITIAL};for(const k of ['format','host','release','experience','publicationHost'])$('#'+k).value=state[k];$('#graph-explanation').textContent='Ausgangslage wiederhergestellt. Der Publikations-Host ist noch offen.';render(true);$('#decision-graph').style.width='100%';$('.graph-viewport').scrollTop=0;$('.graph-viewport').scrollLeft=0;});
document.addEventListener('click',e=>{
 if(e.target.closest('[data-open-architecture]'))$('#architektur').open=true;
 const architectureNode=e.target.closest('[data-architecture-node]');if(architectureNode)explainArchitecture(architectureNode.dataset.architectureNode);
 if(e.target.closest('#download-current-architecture'))downloadArchitecture();
 const cascadeNode=e.target.closest('[data-cascade-node]');if(cascadeNode)explainCascade(cascadeNode.dataset.cascadeNode);
 if(e.target.closest('#download-current-cascade'))downloadCascade();
 const graphNode=e.target.closest('[data-graph-node]');if(graphNode)activateGraphNode(graphNode.dataset.graphNode);
 const zoom=e.target.closest('[data-graph-zoom]');if(zoom){$('#decision-graph').style.width=`${Number(zoom.dataset.graphZoom)*100}%`;}
 const eventButton=e.target.closest('[data-event]');if(eventButton){state.event=eventButton.dataset.event;state.access=state.advice=state.license=state.publicationService='unknown';state.sync=state.backup='unknown';render(true);}
 const starter=e.target.closest('[data-start-event]');if(starter){state.event=starter.dataset.startEvent;state.access=state.advice=state.license=state.publicationService='unknown';state.sync=state.backup='unknown';render(true);}
 const chip=e.target.closest('[data-open-entry]');if(chip){e.preventDefault();openEntryId=chip.dataset.openEntry;const entry=result.entries.find(x=>x.id===openEntryId);$('#entry-dialog-content').innerHTML=`<p class="eyebrow">${entry.type==='c'?'EINE CHANCE FÜR ANNAS PROJEKT':'WORAUF ANNA ACHTEN SOLLTE'}</p><h2 id="entry-dialog-title">${escape(entry.title)}</h2><p class="dialog-rating">${escape(rating(entry))}${entry.status?` · Wirkung: ${entry.w}`:''}</p>${entryExplanation(entry)}<p class="small">Qualitative Modellannahme für fünf Jahre. Kein Gesamturteil über Annas Projekt.</p><button class="text-button" type="button" data-print="topic">Diese Erklärung drucken</button>`;$('#entry-dialog').showModal();}
 const path=e.target.closest('[data-choose-format]');if(path){state.format=path.dataset.chooseFormat;$('#format').value=state.format;render(true);}
 if(e.target.closest('[data-open-guide]'))$('.move-guide').open=true;
 if(e.target.closest('#clear-event')){state.event=null;render(true);}
 if(e.target.closest('#load-leaving')){state.access=state.advice=state.license=state.publicationService='ends';render(true);$('#load-leaving').focus();}
 const printer=e.target.closest('[data-print]');if(printer)printMaterial(printer.dataset.print);
});
function activateGraphNode(id){const node=GRAPH_NODES.find(n=>n.id===id);if(!node)return;if(node.field){state[node.field]=node.value;$('#'+node.field).value=node.value;render(true);$('#flow-'+id)?.focus();}$('#graph-explanation').innerHTML=`<h4>${escape(node.lines[0])}</h4><p>${escape(node.info)}</p>${node.field?'<p class="small">Ihre Auswahl und der hervorgehobene Pfad wurden aktualisiert.</p>':''}`;}
$('#decision-graph').addEventListener('keydown',e=>{const node=e.target.closest('[data-graph-node]');if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activateGraphNode(node.dataset.graphNode);}});
$('#download-current-graph').addEventListener('click',()=>{const blob=new Blob([graphSVG(state,false)],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='anna-entscheidungsgraph-auswahl.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#event-detail').addEventListener('change',e=>{const key=e.target.dataset.condition;if(key){state[key]=e.target.value;render(true,false);if(state.event==='leaving')renderCascade();}});
$('#export').addEventListener('click',()=>{const blob=new Blob([snapshot(state,result)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='annas-strategie.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#sources-link').addEventListener('click',()=>{$('#nachweise').open=true;});
function printHeader(title){return `<div class="print-meta">EDITIONSKOMPASS · ${VERSION} · 20. Oktober 2026<br>Fiktive Persona und qualitative Modellannahmen · Material: ${title}</div>`;}
function printStrategy(){const tasks=taskList();return `<h1>Annas Folgen- und Strategieblatt</h1><p><strong>Format:</strong> ${LABELS.format[state.format]}<br><strong>Arbeitsort:</strong> ${LABELS.host[state.host]}<br><strong>Freigabe:</strong> ${LABELS.release[state.release]}<br><strong>Plattformpraxis:</strong> ${LABELS.experience[state.experience]}<br><strong>Publikations-Host:</strong> ${LABELS.publicationHost[state.publicationHost]}<br><strong>Ereignis:</strong> ${state.event?LABELS.event[state.event]:'Keines'}</p>${state.event==='leaving'?`<p>Repo-Zugang: ${LABELS.availability[state.access]} · Beratung: ${state.host==='uni-only'?'Bereits nicht angeboten':LABELS.availability[state.advice]} · Publikationsdienste: ${LABELS.availability[state.publicationService]} · Werkzeug: ${state.format==='markdown'?'oXygen nicht vorausgesetzt':LABELS.availability[state.license]}</p>`:''}${state.event==='crash'?`<p>Abgleich: ${LABELS.proof[state.sync]} · Unabhängige Sicherung geprüft: ${LABELS.proof[state.backup]}</p>`:''}<h2>Begründungen</h2>${[result.formatText,result.hostText,result.releaseText,result.experienceText].map(t=>`<p>${t}</p>`).join('')}<h2>Aufgaben und Unterstützung</h2><h3>Anna selbst</h3><ul>${tasks.anna.map(t=>`<li>${t}</li>`).join('')}</ul><h3>Benötigte Leistungen</h3><ul>${tasks.services.map(t=>`<li>${t}</li>`).join('')}</ul><p>Offen: Rechte, konkrete Dienstbedingungen, Budget, Vertretung und langfristiger Träger. Maßnahmen gelten als geplant, nicht als nachgewiesen umgesetzt.</p><h2>Chancen und Risiken</h2><p>Horizont fünf Jahre; Plausibilität / Wirkung. „Ungeklärt“ ist kein niedriger Wert. Gesamtinventar-Ausschnitt: fünf Chancen und acht Risiken.</p><table><thead><tr><th>Eintrag</th><th>Ausgang → aktuell</th><th>Grund und Handlung</th></tr></thead><tbody>${result.entries.map(e=>{const b=result.before.find(b=>b.id===e.id);return `<tr><td>${e.title}</td><td>${rating(b)} → ${rating(e)}${e.status?`; Wirkung ${e.w}`:''}</td><td>${e.reason}<br><strong>Handlung:</strong> ${e.action}<br><strong>Zuständig:</strong> ${e.role}</td></tr>`;}).join('')}</tbody></table><h3>Nächste Revision</h3><p>Bei neuem Teammitglied, Teilpublikation, Modellwechsel, bevorstehendem Institutionswechsel oder längerer Unterbrechung; Termin gemeinsam festlegen.</p>`;}
function printMaterial(kind){let html='';
 if(kind==='topic'&&openEntryId){const entry=result.entries.find(e=>e.id===openEntryId);html=`<h1>${escape(entry.title)}</h1><p><strong>${rating(entry)}</strong>${entry.status?`; Wirkung: ${entry.w}`:''}</p>${entryExplanation(entry)}`;}
 if(kind==='graph')html=graphSVG();
 if(kind==='strategy')html=printStrategy();
 if(kind==='persona')html=`<div class="print-persona"><section class="print-card"><p>P01-K01 · PERSONA · VORDERSEITE</p><h1>Anna und die vergessene Schrift</h1><p>Anna kennt einen historischen Text seit Jahren. Frühere Ausgaben sind vergriffen; ohne sprachliche und historische Erläuterungen bleibt vieles unverständlich. Sie möchte eine wissenschaftliche Edition mit Einleitung und Stellenkommentar schaffen – am liebsten auch als Buch.</p><p>Sie arbeitet allein, neben anderen Verpflichtungen und mit wenig Budget. Ihre fachliche Kompetenz ist da; für digitale Arbeitsabläufe braucht sie ein vorbereitetes Umfeld und erreichbare Hilfe. Zeit ist die knappste Ressource.</p><p>Spätere Korrekturen, punktuelles Gegenlesen und ein Ausschnitt für die Lehre sollen möglich bleiben.</p><h3>Die Leitfrage</h3><p>Wie kann Anna einfach beginnen und trotzdem spätere Möglichkeiten offenhalten?</p></section><section class="print-card print-break"><p>P01-K01 · PERSONA · RÜCKSEITE</p><h2>Ziele und Unterstützung</h2><p><strong>Mindestziel:</strong> geprüfte, dokumentierte und freigabefähige Editionsdaten; Archivierung und Identifikation vereinbaren. Web und Druck nach Aufwand ergänzen.</p><p><strong>Bevorzugter Weg:</strong> begrenztes TEI-Modell, vorbereitete oXygen-Author-/Git-Umgebung, Validierung und lokale Vorschau. Eine Lizenz ist damit noch nicht nachgewiesen.</p><p><strong>Einfach arbeiten:</strong> Hauptbranch, sinnvolle Commits, regelmäßiger Abgleich und unabhängige geprüfte Sicherung.</p><p><strong>Institutioneller Bedarf:</strong> Einrichtung, punktuelle Beratung, Freigabeunterstützung und Export-/Übergaberegelung.</p><h3>Zum Diskutieren</h3><p>Was muss Anna selbst tun? Welche Leistung muss verlässlich angeboten werden?</p><p>P01-D01–D03 · P01-R01–R08 · P01-SV01–SV05</p></section></div>`;
 if(kind==='events'){const cards={mira:['Mira liest mit','Eine Kollegin bietet an, einen Abschnitt gegenzulesen. Fachlicher Gewinn wird möglich; Einführung und Integration brauchen Zeit.','Welchen kleinsten Ausschnitt und welchen Rückkanal braucht Mira?'],teaching:['Ein Seminar steht an','Anna möchte eine Passage in der Lehre verwenden. Eine begrenzte Lehrfassung und eine öffentliche Teilpublikation sind verschiedene Freigaben.','Wer soll was sehen, und welche Prüfung ist vor der Freigabe nötig?'],leaving:['Die Uni-Anbindung endet','Repo-Zugang, Beratung und Werkzeugberechtigung können betroffen sein. Jede Folge bleibt einzeln zu klären.','Was bleibt verfügbar, was endet, was ist unbekannt? Wer unterstützt den Wechsel?'],crash:['Der Rechner fällt aus','Der Defekt ist eingetreten. Externer Abgleich und unabhängige Sicherung können unterschiedliche Datenstände erhalten.','Welcher Stand ist vorhanden? Sind Rücksicherung und externe Objekte geprüft?']};html=`<h1>Was wäre, wenn …?</h1><p>Vier mögliche Situationen für Anna. Einzeln diskutieren; keine vorgegebene Projektbiografie.</p><div class="print-cards">${Object.entries(cards).map(([key,[title,text,question]])=>`<section class="print-card"><h2>${title}</h2><p>${text}</p><p><strong>Diskussion:</strong> ${question}</p></section>`).join('')}</div>`;}
 if(kind==='workflow')html=`<h1>Ein einfacher Arbeitsweg für Anna</h1><p>TEI als bevorzugter Einstieg mit vorbereiteter Unterstützung. Format und konkreter Host sind gesonderte Entscheidungen.</p><table><thead><tr><th>Schritt</th><th>Was geschieht?</th><th>Wer trägt es?</th></tr></thead><tbody><tr><td>1. Bearbeiten</td><td>Text und Kommentar im dokumentierten Modell erfassen.</td><td>Anna; Einrichtung mit Beratung</td></tr><tr><td>2. Prüfen</td><td>Validieren und lokale Vorschau ansehen; Fachurteil bleibt nötig.</td><td>Anna; Prüfregeln mit Beratung</td></tr><tr><td>3. Festhalten</td><td>Commit, regelmäßiger externer Abgleich zum privaten Arbeitsrepo.</td><td>Anna; Hosting mit geklärter Verantwortung</td></tr><tr><td>4. Freigeben</td><td>Fachliche Qualität, Rechte, Schutz, Metadaten und erreichbare Historie prüfen; kuratierten Export erzeugen.</td><td>Anna; Fach-/Technikhilfe nach Bedarf</td></tr><tr><td>5. Ausgeben</td><td>Publikationsdaten, statische Website, gegebenenfalls PDF/Druck.</td><td>Vereinbarter Publikationsdienst; fachliche Verantwortung bei Anna</td></tr></tbody></table><h2>Zwei zusätzliche Aufgaben</h2><p><strong>Sicherung:</strong> regelmäßige Commits und Pushs auf ein verlässlich betriebenes Uni-GitLab können Annas Editionsdateien samt Geschichte absichern. Anna testet den Rückweg durch eine frische Kopie, dokumentiert den Umfang und ergänzt für externe Dateien einen Sicherungsweg. Eine zusätzliche unabhängige Kopie verbessert den Schutz.</p><p><strong>Archivierung:</strong> Metadaten, Nutzungsbedingungen, persistente Identifikation und langfristige Trägerschaft gesondert vereinbaren. Git-Hosting garantiert dies nicht.</p><h3>Wechsel vorbereiten</h3><p>Lokalen Build, Export, Rechte und Übergabe erproben. Git-Daten und Historie sind nur ein Teil; Plattformdaten und externe Objekte separat behandeln. Arbeitsort und Publikationsort können verschieden sein.</p>`;
 if(kind==='article')html=$('#mira').innerHTML;
 $('#print-root').innerHTML=(kind==='graph'?'':printHeader(kind))+html;
 let style=$('#print-size');if(!style){style=document.createElement('style');style.id='print-size';document.head.append(style);}style.textContent=`@page{size:${kind==='graph'?'A3 portrait':kind==='workflow'?'A4 landscape':kind==='persona'?'A5 portrait':'A4 portrait'};margin:${kind==='persona'?'10mm':'15mm'}}`;
 if(kind==='persona')style.textContent+='@media print{#print-root .print-persona .print-card{min-height:0;border:0;padding:0}}';
 document.body.dataset.print=kind;window.print();
}
render();
